'use client'

import {
  forwardRef,
  useCallback,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type KeyboardEvent,
} from 'react'
import { motion, useAnimate, useMotionValue, useReducedMotion, type Transition } from 'motion/react'
import { cn } from '@/lib/utils'
import { playHoverSound, playBounceSound } from '@/lib/sound'

const EASE_OUT = [0.22, 1, 0.36, 1] as const

export type BounceSidebarProps = {
  items: string[]
  value?: number
  defaultValue?: number
  onChange?: (index: number) => void
  dotColor?: string
  className?: string
}

const itemClass = (active: boolean) =>
  cn(
    'flex w-full cursor-pointer items-center rounded-md p-1 text-left text-base',
    'transition-colors duration-(--motion-dur-fast) ease-(--motion-ease-out) motion-reduce:transition-none',
    'focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-(--color-accent) focus-visible:ring-offset-1 focus-visible:ring-offset-(--color-bg)',
    active ? 'text-foreground' : 'text-foreground/55',
  )

export const BounceSidebar = forwardRef<HTMLUListElement, BounceSidebarProps>(
  function BounceSidebar(
    { items, value, defaultValue = 0, onChange, dotColor = 'var(--color-accent)', className },
    forwardedRef,
  ) {
    const [internalValue, setInternalValue] = useState(defaultValue)
    const activeIndex = value ?? internalValue

    const [scope, animate] = useAnimate()
    const itemRefs = useRef<(HTMLLIElement | null)[]>([])
    const prevY = useRef<number | null>(null)

    const reduceMotion = useReducedMotion()

    const dotX = useMotionValue(0)
    const dotY = useMotionValue(0)

    const dotSize = useSyncExternalStore(
      () => () => {},
      () => Math.round(6 * (window.devicePixelRatio || 1)) / (window.devicePixelRatio || 1),
      () => 6,
    )

    const getTargetY = (index: number, size: number): number | null => {
      const el = itemRefs.current[index]
      if (!el) return null
      const dpr = window.devicePixelRatio || 1
      return Math.round((el.offsetTop + el.offsetHeight / 2 - size / 2) * dpr) / dpr
    }

    useEffect(() => {
      let cancelled = false
      const dpr = window.devicePixelRatio || 1
      const computedSize = Math.round(6 * dpr) / dpr

      const initialIndex = activeIndex
      const snap = () => {
        if (cancelled) return
        const toY = getTargetY(initialIndex, computedSize)
        if (toY === null) return
        dotX.set(0)
        dotY.set(toY)
        prevY.current = toY
      }

      const ro = new ResizeObserver(snap)
      itemRefs.current.forEach((el) => el && ro.observe(el))

      const raf = requestAnimationFrame(snap)
      document.fonts?.ready.then(snap)
      return () => {
        cancelled = true
        cancelAnimationFrame(raf)
        ro.disconnect()
      }
      // mount-only: snap reads refs/motion values, not reactive deps
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [])

    useEffect(() => {
      const toY = getTargetY(activeIndex, dotSize)
      if (toY === null) return

      if (prevY.current === null) {
        dotX.set(0)
        dotY.set(toY)
        prevY.current = toY
        return
      }

      const fromY = prevY.current
      const delta = toY - fromY
      prevY.current = toY
      if (delta === 0) return
      const distance = Math.abs(delta)
      if (!reduceMotion) playBounceSound()

      if (reduceMotion) {
        dotX.set(0)
        dotY.set(toY)
        return
      }

      const yDuration = 0.45
      const yTransition: Transition = { duration: yDuration, ease: EASE_OUT }

      const strength = Math.min(0.6, 20 / distance)
      const peakX = -strength * distance

      animate(dotY, toY, yTransition)
      animate(dotX, [0, peakX, 0], {
        duration: yDuration,
        ease: EASE_OUT,
        times: [0, 0.4, 1],
      })
    }, [activeIndex, animate, dotX, dotY, dotSize, reduceMotion])

    const select = useCallback(
      (index: number) => {
        playBounceSound()
        if (value === undefined) setInternalValue(index)
        onChange?.(index)
      },
      [value, onChange],
    )

    const handleKeyDown = useCallback(
      (e: KeyboardEvent<HTMLUListElement>) => {
        const count = items.length
        if (count === 0) return

        let next = activeIndex

        if (e.key === 'ArrowDown') {
          e.preventDefault()
          next = (activeIndex + 1) % count
        } else if (e.key === 'ArrowUp') {
          e.preventDefault()
          next = (activeIndex - 1 + count) % count
        } else if (e.key === 'Home') {
          e.preventDefault()
          next = 0
        } else if (e.key === 'End') {
          e.preventDefault()
          next = count - 1
        }

        if (next !== activeIndex) {
          select(next)
          const buttons = itemRefs.current.map((el) => el?.querySelector('button'))
          buttons[next]?.focus()
        }
      },
      [activeIndex, items.length, select],
    )

    return (
      <ul
        ref={forwardedRef}
        role="listbox"
        aria-label="Navigation"
        onKeyDown={handleKeyDown}
        className={cn('relative flex flex-col gap-1 ps-6', className)}
      >
        <motion.span
          ref={scope}
          aria-hidden
          className="absolute inset-s-2 top-0 rounded-full"
          style={{
            x: dotX,
            y: dotY,
            width: dotSize,
            height: dotSize,
            backgroundColor: dotColor,
          }}
        />

        {items.map((item, index) => {
          const isActive = index === activeIndex
          return (
            <li
              key={item}
              ref={(el) => {
                itemRefs.current[index] = el
              }}
            >
              <motion.button
                type="button"
                role="option"
                aria-selected={isActive}
                tabIndex={isActive ? 0 : -1}
                onMouseEnter={() => playHoverSound()}
                onClick={() => select(index)}
                aria-current={isActive ? 'true' : undefined}
                whileTap={reduceMotion ? undefined : { scale: 0.97 }}
                className={itemClass(isActive)}
              >
                {item}
              </motion.button>
            </li>
          )
        })}
      </ul>
    )
  },
)

BounceSidebar.displayName = 'BounceSidebar'

'use client'

const MUTE_KEY = 'sound-muted'
const MUTE_EVENT = 'sound-mute-change'

let muted = false
if (typeof window !== 'undefined') {
  try {
    muted = localStorage.getItem(MUTE_KEY) === '1'
  } catch {}
}

export function isSoundMuted(): boolean {
  return muted
}

export function setSoundMuted(value: boolean) {
  muted = value
  if (typeof window !== 'undefined') {
    try {
      localStorage.setItem(MUTE_KEY, value ? '1' : '0')
    } catch {}
    window.dispatchEvent(new CustomEvent(MUTE_EVENT))
  }
}

export function toggleSoundMuted(): boolean {
  setSoundMuted(!muted)
  return muted
}

export function subscribeSoundMuted(callback: () => void) {
  if (typeof window === 'undefined') return () => {}
  window.addEventListener(MUTE_EVENT, callback)
  const onStorage = (e: StorageEvent) => {
    if (e.key === MUTE_KEY) callback()
  }
  window.addEventListener('storage', onStorage)
  return () => {
    window.removeEventListener(MUTE_EVENT, callback)
    window.removeEventListener('storage', onStorage)
  }
}

let audioCtx: AudioContext | null = null

function initAudio(): AudioContext | null {
  if (typeof window === 'undefined') return null
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    if (AudioContextClass) {
      audioCtx = new AudioContextClass()
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {})
  }
  return audioCtx
}

if (typeof window !== 'undefined') {
  const unlock = () => {
    initAudio()
    window.removeEventListener('pointerdown', unlock)
    window.removeEventListener('keydown', unlock)
    window.removeEventListener('touchstart', unlock)
  }
  window.addEventListener('pointerdown', unlock, { passive: true })
  window.addEventListener('keydown', unlock, { passive: true })
  window.addEventListener('touchstart', unlock, { passive: true })
}

export function getAudioContext(): AudioContext | null {
  return initAudio()
}

export function playHoverSound(volume = 0.12, pitch = 1.2) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1400 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(350 * pitch, now + 0.012)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.012)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.012)
  } catch {}
}

export function playClickSound(volume = 0.2, pitch = 1.0) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'triangle'
    osc.frequency.setValueAtTime(850 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(160 * pitch, now + 0.02)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.02)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.02)
  } catch {}
}

export function playTickSound(volume = 0.1, pitch = 1.5) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1800 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(450 * pitch, now + 0.01)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.01)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.01)
  } catch {}
}

export function playTileNote(frequency = 440, volume = 0.08) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime
    const dur = 1.1

    const osc = ctx.createOscillator()
    const shimmer = ctx.createOscillator()
    const shimmerGain = ctx.createGain()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(frequency, now)
    shimmer.type = 'sine'
    shimmer.frequency.setValueAtTime(frequency * 2, now)

    shimmerGain.gain.setValueAtTime(0.22, now)
    shimmerGain.gain.exponentialRampToValueAtTime(0.0001, now + dur * 0.5)

    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.015)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + dur)

    shimmer.connect(shimmerGain)
    shimmerGain.connect(gain)
    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + dur)
    shimmer.start(now)
    shimmer.stop(now + dur)
  } catch {}
}

export function playBounceSound(volume = 0.3, pitch = 1.0) {
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(260 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(650 * pitch, now + 0.04)
    osc.frequency.exponentialRampToValueAtTime(190 * pitch, now + 0.14)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.14)

    const subOsc = ctx.createOscillator()
    const subGain = ctx.createGain()

    subOsc.type = 'triangle'
    subOsc.frequency.setValueAtTime(420 * pitch, now)
    subOsc.frequency.exponentialRampToValueAtTime(120 * pitch, now + 0.05)

    subGain.gain.setValueAtTime(volume * 0.7, now)
    subGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.05)

    subOsc.connect(subGain)
    subGain.connect(ctx.destination)

    subOsc.start(now)
    subOsc.stop(now + 0.05)
  } catch {}
}
